var TITLE = "[Sion] Advanced SAT Reading";var QUIZ_KEY = "quiz_sionadvreading_12_2026-09-11_v1";var ATT_KEY = "quiz_sionadvreading_12_att_2026-09-11_v1";var REPORT_ENDPOINT = 'https://script.google.com/macros/s/AKfycbzRYITi7Q4ttOMcqHPBQ_mfc1m-Oyk_ne-7OKeRGbR_WFEUAe9oCKiC9E7f3ymZWR6i/exec';var RAW_QUESTIONS = [{"tag": "Words in Context", "tagcolor": "#7b61ff", "passage": "Although the committee's final report was ostensibly a routine budget review, its authors had clearly woven in a pointed critique of the department's spending priorities, couched in the dry, procedural language of fiscal analysis.", "stem": "As used in the text, \"couched\" most nearly means", "opts": ["physically hidden inside a piece of furniture", "translated into a completely different language", "expressed in a particular, often indirect, style or form", "loudly announced without any subtlety"], "ci": 2, "exp": "\"Couched in\" describes how the critique was phrased or framed &mdash; here, in dry procedural language &mdash; which matches the meaning \"expressed in a particular style,\" not physical concealment, loud announcement, or literal translation."}, {"tag": "Inferences", "tagcolor": "#f5a623", "passage": "In a study of urban crows, researchers observed that individuals raised near university campuses solved novel puzzle-boxes to obtain food nearly twice as fast as crows raised in rural areas, despite no difference between the two groups' performance on simpler, previously encountered tasks.", "stem": "Which choice is best supported by the passage?", "opts": ["Exposure to a more complex or novel environment, such as a university campus, may specifically enhance crows' ability to solve unfamiliar problems.", "Urban crows perform better than rural crows on all tasks, regardless of familiarity.", "Rural crows are generally less intelligent than urban crows in every measurable respect.", "The study proves that crow intelligence is determined entirely by genetics."], "ci": 0, "exp": "Because the two groups performed equally on familiar tasks but differently on novel ones, the passage supports a link between campus environments and problem-solving with new challenges specifically, not general intelligence or genetics."}, {"tag": "Cross-Text Connections", "tagcolor": "#d6336c", "passage": "Text 1: Proponents of universal basic income argue that a guaranteed monthly payment would reduce the anxiety of poverty and free recipients to pursue education, caregiving, or entrepreneurship without fear of destitution.<br><br>Text 2: Critics of guaranteed income programs point to pilot studies in which recipients, freed from the immediate pressure of low-wage work, reduced their weekly work hours substantially, raising questions about whether such programs might inadvertently shrink the labor supply.", "stem": "Based on the texts, how would the author of Text 2 most likely respond to the claim in Text 1 that guaranteed income allows recipients to pursue entrepreneurship?", "opts": ["By denying that any guaranteed income pilot studies have ever been conducted.", "With skepticism, since the pilot data Text 2 cites suggests recipients may simply work fewer hours rather than redirect that time toward new ventures.", "With full agreement, since Text 2 confirms recipients used their free time exclusively to start new businesses.", "By arguing that guaranteed income payments should be increased even further."], "ci": 1, "exp": "Text 2's evidence shows reduced work hours without confirming a shift toward entrepreneurship, so its author would likely be skeptical of the specific claim that freed-up time in Text 1 translates into new ventures."}, {"tag": "Cross-Text Connections", "tagcolor": "#d6336c", "passage": "Text 1: Marine biologists studying coral bleaching have found that reefs exposed to brief, moderate heat stress earlier in the season often display greater resilience to the more severe heat waves that follow, a phenomenon researchers term \"thermal priming.\"<br><br>Text 2: Not all coral species respond identically to thermal priming; several fast-growing branching corals showed no improved resilience after mild heat exposure, and some even bleached more readily during subsequent heat waves.", "stem": "Based on the texts, the author of Text 2 would most likely respond to the concept of thermal priming discussed in Text 1 by", "opts": ["qualifying it, noting that its protective effect appears to vary significantly across different coral species.", "rejecting it entirely as unsupported by any evidence.", "endorsing it as universally applicable to every coral species.", "ignoring it in favor of a completely unrelated explanation for bleaching."], "ci": 0, "exp": "Text 2 does not deny thermal priming outright but complicates it, showing the effect does not hold for all species, which is best described as qualifying rather than rejecting or fully endorsing the concept."}, {"tag": "Craft and Structure", "tagcolor": "#E24B4A", "passage": "The following text is adapted from a 2020 essay on urban design.<br><br>Traffic engineers have long treated the crosswalk as a mere appendage to the roadway, a concession squeezed between lanes engineered primarily for the unimpeded flow of automobiles. Yet in cities that have reimagined the crosswalk as a destination in its own right &mdash; widened, shaded, and furnished with benches &mdash; pedestrian injuries have fallen even as pedestrian volume has risen.", "stem": "What function does the phrase \"a mere appendage to the roadway\" serve in the text?", "opts": ["It provides a formal engineering definition used consistently throughout the passage.", "It summarizes the passage's overall statistical findings about injuries.", "It expresses the author's own preferred design philosophy for crosswalks.", "It characterizes the traditional, dismissive view of crosswalks that the rest of the passage goes on to challenge."], "ci": 3, "exp": "The phrase sets up the old, dismissive attitude toward crosswalks, which the passage then contrasts with cities that redesigned crosswalks and saw injuries fall &mdash; a classic old-view-versus-new-evidence structure."}, {"tag": "Words in Context", "tagcolor": "#7b61ff", "passage": "The senator's remarks, though measured in tone, were widely interpreted as a tacit rebuke of her own party's leadership, a criticism delivered without ever naming a single colleague.", "stem": "As used in the text, \"tacit\" most nearly means", "opts": ["implied or understood without being directly stated", "officially documented in writing", "extremely loud and openly aggressive", "completely accidental and unintended"], "ci": 0, "exp": "Since the rebuke was delivered \"without ever naming a single colleague,\" it was implied rather than explicit, matching the meaning of \"tacit\" as unstated but understood."}, {"tag": "Craft and Structure", "tagcolor": "#E24B4A", "passage": "The following text is adapted from a 1911 short story.<br><br>Marguerite had always regarded her uncle's silence as a kind of eloquence, a refusal to fill the air with the trivial noise that lesser men mistook for wisdom. It was only after his death, sorting through the ledgers he had kept with such fastidious care, that she understood the silence differently: not as reticence chosen, but as a habit cultivated to conceal the arithmetic of a fortune quietly, methodically, dismantled.", "stem": "What is the function of the word \"eloquence\" in the text as a whole?", "opts": ["It initially frames the uncle's silence as admirable, setting up an ironic contrast with the truth Marguerite later discovers.", "It suggests that the uncle was widely admired as a public speaker.", "It literally describes the pleasant sound of the uncle's voice.", "It emphasizes that Marguerite disliked her uncle from the very beginning."], "ci": 0, "exp": "Calling the silence \"eloquence\" initially casts it as a virtue, but this framing is undercut once Marguerite discovers the silence actually concealed the quiet dismantling of the family fortune, creating dramatic irony."}, {"tag": "Text Structure and Purpose", "tagcolor": "#0d9488", "passage": "Early proponents of a universal grammar hypothesized that all human languages share a deep, innate structural blueprint, despite their surface differences. Decades of subsequent fieldwork among genetically unrelated language communities have complicated this picture: some languages appear to lack grammatical features once assumed universal, such as recursive embedding, prompting a reconsideration of just how \"universal\" any underlying blueprint truly is.", "stem": "How does the text mainly progress?", "opts": ["It presents an established theoretical claim and then complicates it with contradicting evidence from later research.", "It offers a step-by-step methodology for conducting linguistic fieldwork.", "It presents two competing theories and shows that both were later proven completely correct.", "It narrates the biography of a single influential linguist."], "ci": 0, "exp": "The text begins with the universal grammar hypothesis and then introduces fieldwork findings that complicate it, following a claim-then-complication structure rather than a methodology, biography, or confirmation of two theories."}, {"tag": "Command of Evidence", "tagcolor": "#1D9E75", "passage": "A public health researcher hypothesizes that installing streetlights in a high-crime neighborhood will reduce nighttime burglary rates by increasing the perceived risk of detection for potential offenders.", "stem": "Which finding, if true, would most directly support the researcher's hypothesis?", "opts": ["The cost of installing the streetlights was lower than city officials had originally projected.", "The neighborhoods studied also increased police patrols at the same time the streetlights were installed.", "Neighborhoods that installed new streetlights saw nighttime burglary rates fall by 25%, while daytime burglary rates, unaffected by lighting, remained unchanged.", "Residents reported feeling safer walking at night after the streetlights were installed."], "ci": 2, "exp": "A drop specifically in nighttime burglary (when lighting matters) with no change in daytime burglary (when lighting is irrelevant) isolates lighting as the likely cause, directly supporting the hypothesis; the other findings either confound the result or measure something other than actual burglary rates."}, {"tag": "Text Structure and Purpose", "tagcolor": "#0d9488", "passage": "A common assumption holds that ancient trade routes primarily moved luxury goods, such as silk and spices, between distant civilizations. Yet archaeological evidence from way-stations along these routes reveals enormous quantities of mundane items &mdash; salt, grain, and everyday pottery &mdash; suggesting that these corridors functioned as essential arteries of regional subsistence long before they earned their reputation for exotic commerce.", "stem": "What is the main purpose of the text?", "opts": ["To provide a complete chronological history of the silk trade from its origins to its decline.", "To challenge a popular assumption about ancient trade routes by presenting archaeological evidence of a different, more mundane primary function.", "To argue that luxury goods were never transported along these routes at all.", "To describe the architectural features of ancient way-stations in detail."], "ci": 1, "exp": "The passage opens with a widely held assumption and then presents archaeological evidence that complicates it, which is characteristic of a text whose purpose is to challenge that assumption."}, {"tag": "Command of Evidence", "tagcolor": "#1D9E75", "passage": "An economist argues that a proposed tax credit for first-time homebuyers will primarily benefit middle-income families rather than the wealthy, since the credit phases out entirely for households earning above a moderate income threshold.", "stem": "Which finding, if true, would most directly undermine the economist's argument?", "opts": ["The credit's total cost to the federal government was higher than initially estimated.", "The tax credit is scheduled to expire after five years unless renewed by Congress.", "Middle-income families reported high satisfaction with the credit in a recent survey.", "An analysis shows that most claimed credits went to households whose income, after accounting for other tax shelters, actually placed them among the wealthiest 10% of homebuyers."], "ci": 3, "exp": "If wealthy households were actually the main beneficiaries despite the income cutoff, that would directly contradict the claim that the credit primarily benefits middle-income families."}, {"tag": "Inferences", "tagcolor": "#f5a623", "passage": "A team studying nocturnal pollinators placed motion-activated cameras near flowering cacti in the Sonoran Desert. Long-nosed bats visited flowers that had been in bloom for less than twelve hours far more frequently than flowers older than twenty-four hours, even when the older flowers still contained substantial nectar reserves.", "stem": "Which choice is best supported by the passage?", "opts": ["Bats are incapable of detecting any nectar in flowers older than twenty-four hours.", "Long-nosed bats only ever visit flowers during daylight hours.", "Older flowers in the study produced no nectar whatsoever.", "Bats may rely on cues other than nectar quantity alone, such as floral freshness, when selecting which flowers to visit."], "ci": 3, "exp": "Since older flowers still had substantial nectar but were visited far less, bats must be responding to some cue besides nectar quantity, such as the flower's freshness, rather than an inability to detect nectar."}];var N = RAW_QUESTIONS.length;var ORDER_KEY = QUIZ_KEY + '_order_v1';
function shuffleArr(arr){
  var a = arr.slice();
  for(var i=a.length-1;i>0;i--){
    var j = Math.floor(Math.random()*(i+1));
    var t=a[i]; a[i]=a[j]; a[j]=t;
  }
  return a;
}
function identityOrder(){var o=[];for(var i=0;i<N;i++)o.push(i);return o;}
function isValidOrder(arr){
  if(!Array.isArray(arr) || arr.length===0) return false;
  for(var i=0;i<arr.length;i++){ if(typeof arr[i] !== 'number' || arr[i]<0 || arr[i]>=N) return false; }
  return true;
}
function loadOrder(){
  try{
    var raw = localStorage.getItem(ORDER_KEY);
    if(!raw) return null;
    var arr = JSON.parse(raw);
    if(!isValidOrder(arr)) throw new Error('bad');
    return arr;
  }catch(e){ try{localStorage.removeItem(ORDER_KEY);}catch(e2){} return null; }
}
function saveOrder(o){ try{ localStorage.setItem(ORDER_KEY, JSON.stringify(o)); }catch(e){} }

var order = loadOrder() || identityOrder();
if(!loadOrder()) saveOrder(order);
var pendingFreshMode = 'original';

function defaultState(){
  return { cur:0, answers:{}, showResults:false, timerTotalSec:null, timerStartedAt:null };
}
function loadState(){
  try{
    var raw = localStorage.getItem(QUIZ_KEY);
    if(!raw) return defaultState();
    var s = JSON.parse(raw);
    if(typeof s.cur !== 'number' || s.cur<0 || s.cur>=order.length) s.cur = 0;
    if(typeof s.answers !== 'object' || s.answers===null) s.answers = {};
    if(typeof s.showResults !== 'boolean') s.showResults = false;
    if(typeof s.timerTotalSec === 'undefined') s.timerTotalSec = null;
    if(typeof s.timerStartedAt === 'undefined') s.timerStartedAt = null;
    return s;
  }catch(e){ try{localStorage.removeItem(QUIZ_KEY);}catch(e2){} return defaultState(); }
}
function saveState(){ try{ localStorage.setItem(QUIZ_KEY, JSON.stringify(state)); }catch(e){} }

var state = loadState();
var timerInterval = null;

function getAttempts(){ try{ return parseInt(localStorage.getItem(ATT_KEY)||'0',10); }catch(e){ return 0; } }
function incAttempts(){ try{ localStorage.setItem(ATT_KEY, String(getAttempts()+1)); }catch(e){} }
function updateAttDisplay(){
  var el = document.getElementById('att-display');
  if(el) el.textContent = 'Total Attempts: ' + getAttempts();
}

function formatTime(sec){
  sec = Math.max(0, Math.round(sec));
  var m = Math.floor(sec/60), s = sec%60;
  return String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');
}
function renderTimer(){
  var setupEl = document.getElementById('timerSetup');
  var runningEl = document.getElementById('timerRunning');
  var dispEl = document.getElementById('timerDisplay');
  if(!setupEl||!runningEl||!dispEl) return;
  if(!state.timerStartedAt){ setupEl.style.display='flex'; runningEl.style.display='none'; return; }
  setupEl.style.display='none'; runningEl.style.display='flex';
  var elapsed = (Date.now()-state.timerStartedAt)/1000;
  var remaining = state.timerTotalSec - elapsed;
  dispEl.classList.remove('warn','danger');
  if(remaining<=0){ dispEl.textContent="Time's Up"; dispEl.classList.add('danger'); stopTimerInterval(); return; }
  dispEl.textContent = formatTime(remaining);
  if(remaining <= state.timerTotalSec*0.1) dispEl.classList.add('danger');
  else if(remaining <= state.timerTotalSec*0.25) dispEl.classList.add('warn');
}
function startTimer(){
  var input = document.getElementById('timerMinutesInput');
  var minutes = parseFloat(input.value);
  if(!minutes || minutes<=0) minutes=20;
  state.timerTotalSec = Math.round(minutes*60);
  state.timerStartedAt = Date.now();
  saveState(); renderTimer(); startTimerInterval();
}
function startTimerInterval(){ stopTimerInterval(); timerInterval=setInterval(renderTimer,1000); }
function stopTimerInterval(){ if(timerInterval){clearInterval(timerInterval); timerInterval=null;} }
function resetTimer(){
  state.timerTotalSec = null; state.timerStartedAt = null;
  stopTimerInterval(); saveState(); renderTimer();
}

function render(){
  updateAttDisplay();
  var qa = document.getElementById('quiz-area');
  var rs = document.getElementById('results-screen');
  if(state.showResults){
    qa.style.display='none';
    rs.classList.add('show');
    renderResults();
    return;
  }
  qa.style.display='block';
  rs.classList.remove('show');

  var qi = order[state.cur];
  var q = RAW_QUESTIONS[qi];
  document.getElementById('q-num').textContent = 'Q' + (state.cur+1) + ' / ' + order.length;

  var badge = document.getElementById('tag-badge');
  if(q.tag){
    badge.style.display='inline-block';
    badge.textContent = q.tag;
    badge.style.background = q.tagcolor || '#185FA5';
  } else { badge.style.display='none'; }

  var pbox = document.getElementById('passage-box');
  if(q.passage){ pbox.style.display='block'; pbox.innerHTML = q.passage; } else { pbox.style.display='none'; }
  var cbox = document.getElementById('context-box');
  if(q.context){ cbox.style.display='block'; cbox.innerHTML = q.context; } else { cbox.style.display='none'; }

  document.getElementById('q-text').innerHTML = q.stem;

  var answered = state.answers[qi];
  var optDiv = document.getElementById('options');
  optDiv.innerHTML='';
  q.opts.forEach(function(optText, idx){
    var btn = document.createElement('button');
    btn.className='opt-btn';
    btn.innerHTML = optText;
    btn.disabled = answered !== undefined;
    if(answered !== undefined){
      if(idx === q.ci) btn.classList.add(answered===idx ? 'correct' : 'revealed');
      else if(answered === idx) btn.classList.add('wrong');
    }
    btn.onclick = function(){ chooseAnswer(idx); };
    optDiv.appendChild(btn);
  });

  var expDiv = document.getElementById('exp-box');
  if(answered !== undefined && answered !== q.ci){
    expDiv.style.display='block';
    expDiv.innerHTML = q.exp;
  } else {
    expDiv.style.display='none';
  }

  var nextBtn = document.getElementById('next-btn');
  nextBtn.textContent = (state.cur >= order.length-1) ? 'Show Results →' : 'Next →';

  updateNav();
  if(window.postRenderHook) window.postRenderHook();

}

function updateNav(){
  var answered=0;
  for(var k=0;k<order.length;k++){ if(state.answers[order[k]]!==undefined) answered++; }
  document.getElementById('nav-count').textContent = answered + ' / ' + order.length;
  document.getElementById('prog-fill').style.width = (answered/order.length*100).toFixed(1)+'%';
  renderDots();
}
function renderDots(){
  var panel = document.getElementById('dot-panel');
  if(panel.style.display==='none') return;
  var html='';
  for(var pos=0; pos<order.length; pos++){
    var qi = order[pos];
    var bg = state.answers[qi]===undefined ? '#d7dde6' : (state.answers[qi]===RAW_QUESTIONS[qi].ci ? '#185FA5' : '#E24B4A');
    html += '<button class="dot" style="background:'+bg+';" onclick="goToQ('+pos+')">'+(pos+1)+'</button>';
  }
  var answered=0;
  for(var k=0;k<order.length;k++){ if(state.answers[order[k]]!==undefined) answered++; }
  if(answered===order.length){
    html += '<br><button class="results-pill" onclick="showResultsNow()">Results</button>';
  }
  panel.innerHTML = html;
}
function toggleJump(){
  var panel = document.getElementById('dot-panel');
  var btn = document.getElementById('jump-btn');
  if(panel.style.display==='none' || panel.style.display===''){
    panel.style.display='block'; btn.innerHTML='Hide &#9652;'; renderDots();
  } else {
    panel.style.display='none'; btn.innerHTML='Jump &#9662;';
  }
}
function goToQ(pos){
  state.cur = pos; state.showResults=false; saveState(); render();
}
function showResultsNow(){
  state.showResults = true; incAttempts(); saveState(); render(); reportResult();
}
function chooseAnswer(idx){
  var qi = order[state.cur];
  if(state.answers[qi] !== undefined) return;
  state.answers[qi] = idx;
  saveState(); render();
}
function goPrev(){
  if(state.cur>0){ state.cur--; saveState(); render(); }
}
function goNext(){
  if(state.cur < order.length-1){ state.cur++; saveState(); render(); }
  else { state.showResults=true; incAttempts(); saveState(); render(); reportResult(); }
}
function reportResult(){
  try{
    var correct=0, wrong=0, skipped=0;
    for(var pos=0; pos<order.length; pos++){
      var qi = order[pos];
      if(state.answers[qi]===undefined){ skipped++; continue; }
      if(state.answers[qi]===RAW_QUESTIONS[qi].ci) correct++; else wrong++;
    }
    var total = order.length;
    var childName = 'Unknown';
    if(TITLE.indexOf('[Sion]')===0) childName='Sion';
    else if(TITLE.indexOf('[Grant]')===0) childName='Grant';
    else if(TITLE.indexOf('[Both]')===0) childName='Both';
    else if(TITLE.indexOf('[Review]')===0) childName='Review';
    var payload = {
      child: childName,
      quizTitle: TITLE,
      quizKey: QUIZ_KEY,
      attemptNumber: getAttempts(),
      correct: correct, wrong: wrong, skipped: skipped, total: total,
      scorePercent: total>0 ? Math.round((correct/total)*1000)/10 : 0
    };
    fetch(REPORT_ENDPOINT, {
      method: 'POST',
      mode: 'no-cors',
      headers: {'Content-Type': 'text/plain;charset=utf-8'},
      body: JSON.stringify(payload)
    }).catch(function(){});
  }catch(e){}
}
function renderResults(){
  var correct=0, wrong=0, skipped=0;
  for(var pos=0; pos<order.length; pos++){
    var qi = order[pos];
    if(state.answers[qi]===undefined){ skipped++; continue; }
    if(state.answers[qi]===RAW_QUESTIONS[qi].ci) correct++; else wrong++;
  }
  document.getElementById('results-score').textContent = correct+' correct, '+wrong+' wrong, '+skipped+' skipped - out of '+order.length;
  var grid = document.getElementById('results-grid');
  grid.innerHTML='';
  for(var pos=0; pos<order.length; pos++){
    var qi = order[pos];
    var card = document.createElement('div');
    if(state.answers[qi]===undefined){
      card.className='r-card skipped';
      card.textContent='Q'+(pos+1)+' Skip';
    } else {
      var ok = state.answers[qi]===RAW_QUESTIONS[qi].ci;
      card.className='r-card '+(ok?'correct':'wrong');
      card.textContent='Q'+(pos+1)+' '+(ok?'OK':'X');
    }
    (function(p){ card.onclick=function(){ state.showResults=false; state.cur=p; saveState(); render(); }; })(pos);
    grid.appendChild(card);
  }
}
function retryWrong(){
  var wrong=[];
  for(var pos=0; pos<order.length; pos++){
    var qi = order[pos];
    if(state.answers[qi]!==undefined && state.answers[qi]!==RAW_QUESTIONS[qi].ci){
      wrong.push(qi);
    }
  }
  if(wrong.length===0) return;
  wrong.forEach(function(qi){ delete state.answers[qi]; });
  order = wrong;
  saveOrder(order);
  state.cur=0; state.showResults=false;
  saveState(); render(); renderTimer();
}
function copyRes(){
  var lines=[TITLE+' Results'];
  for(var pos=0; pos<order.length; pos++){
    var qi = order[pos];
    var a = state.answers[qi];
    var s='Q'+(pos+1)+': ';
    if(a===undefined) s+='Skipped';
    else s += (a===RAW_QUESTIONS[qi].ci ? 'Correct' : 'Wrong');
    lines.push(s);
  }
  var text = lines.join('\n');
  try{
    if(navigator.clipboard){ navigator.clipboard.writeText(text).catch(function(){}); }
    else { var ta=document.createElement('textarea'); ta.value=text; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); document.body.removeChild(ta); }
  }catch(e){}
}
function saveWrongAnswers(){
  var wrongItems=[];
  for(var pos=0; pos<order.length; pos++){
    var qi = order[pos];
    var a = state.answers[qi];
    if(a!==undefined && a!==RAW_QUESTIONS[qi].ci){
      var q = RAW_QUESTIONS[qi];
      wrongItems.push({ question: q.stem, yourAnswer: q.opts[a], correctAnswer: q.opts[q.ci], explanation: q.exp });
    }
  }
  var blob = new Blob([JSON.stringify({title:TITLE, wrongAnswers:wrongItems}, null, 2)], {type:'application/json'});
  var url = URL.createObjectURL(blob);
  var a2 = document.createElement('a');
  a2.href = url; a2.download = QUIZ_KEY + '_wrong.json';
  document.body.appendChild(a2); a2.click(); document.body.removeChild(a2);
  URL.revokeObjectURL(url);
}
function openFreshModal(mode){
  pendingFreshMode = mode;
  var t = document.getElementById('freshModalTitle');
  var m = document.getElementById('freshModalText');
  if(mode==='random'){
    t.textContent='Start Fresh (Random Order)?';
    m.textContent='Questions will be reshuffled into a new random order, and all progress will be cleared. This cannot be undone.';
  } else {
    t.textContent='Start Fresh (Original Order)?';
    m.textContent='Questions will return to their original order, and all progress will be cleared. This cannot be undone.';
  }
  document.getElementById('freshModal').classList.add('show');
}
function openFreshModalOriginal(){ openFreshModal('original'); }
function openFreshModalRandom(){ openFreshModal('random'); }
function closeFreshModal(){ document.getElementById('freshModal').classList.remove('show'); }
function confirmFresh(){
  order = (pendingFreshMode==='random') ? shuffleArr(identityOrder()) : identityOrder();
  saveOrder(order);
  state = defaultState();
  saveState();
  resetTimer();
  closeFreshModal();
  render();
  renderTimer();
}

window.startTimer=startTimer;
window.toggleJump=toggleJump;
window.goToQ=goToQ;
window.showResultsNow=showResultsNow;
window.chooseAnswer=chooseAnswer;
window.goPrev=goPrev;
window.goNext=goNext;
window.retryWrong=retryWrong;
window.copyRes=copyRes;
window.saveWrongAnswers=saveWrongAnswers;
window.openFreshModalOriginal=openFreshModalOriginal;
window.openFreshModalRandom=openFreshModalRandom;
window.closeFreshModal=closeFreshModal;
window.confirmFresh=confirmFresh;

render();
renderTimer();
if(state.timerStartedAt) startTimerInterval();

